              <b-badge :variant="getInstallmentStatusVariant(selectedInstallment)" pill>
                {{ getInstallmentStatusLabel(selectedInstallment) }}
              </b-badge>
            </b-col>
          </b-row>
        </b-card>

        <!-- Valores -->
        <div class="payment-summary mb-3">
          <div class="d-flex justify-content-between py-2 border-bottom">
            <span class="text-muted">Valor da prestação</span>
            <strong>{{ formatCurrency(selectedInstallment.installment) }}</strong>
          </div>
          <div v-if="selectedLateDays > 0" class="d-flex justify-content-between align-items-center py-2 border-bottom">
            <span class="text-danger">
              Juros de mora
              <small class="d-block text-danger" style="font-weight: normal">
                ({{ selectedLateDays }} {{ selectedLateDays === 1 ? 'dia' : 'dias' }} em atraso x {{ companyData.forfeit }}%/dia)
              </small>
            </span>
            <strong class="text-danger">{{ formatCurrency(selectedForfeit) }}</strong>
          </div>
          <div class="d-flex justify-content-between py-2 bg-success-light rounded px-2 mt-2">
            <strong>Total a pagar</strong>
            <strong class="text-success" style="font-size: 1.2rem">
              {{ formatCurrency(selectedTotal) }}
            </strong>
          </div>
        </div>

        <!-- Outros Canais de Pagamento -->
        <b-card v-if="accounts && accounts.length > 0" class="border-info mb-3">
          <h6 class="font-weight-bold mb-2">
            <b-icon icon="credit-card" class="mr-1 text-info"></b-icon>
            Outros Canais de Pagamento
          </h6>
          <p class="small text-muted mb-2">
            Pode também efectuar o pagamento através dos seguintes canais:
          </p>
          <div
            v-for="(acc, idx) in accounts"
            :key="acc.id"
            class="d-flex align-items-start p-2 rounded mb-1"
            :class="idx % 2 === 0 ? 'bg-light' : ''"
          >
            <b-icon icon="building" class="mr-2 mt-1 text-secondary" font-scale="1.1"></b-icon>
            <div class="flex-grow-1">
              <div class="font-weight-bold small">{{ acc.accountDescription || 'Conta de Pagamento' }}</div>
              <div class="d-flex justify-content-between align-items-center">
                <span class="small text-muted">{{ acc.accountHolder || '--' }}</span>
                <code class="text-primary font-weight-bold" style="font-size: 0.85em; letter-spacing: 0.5px">{{ acc.accountNumber }}</code>
              </div>
            </div>
          </div>
          <div class="text-center mt-2">
            <small class="text-muted">
              Após o pagamento, envie o comprovativo para a instituição.
            </small>
          </div>
        </b-card>

        <!-- Informação M-Pesa USSD -->
        <b-card class="border-success mb-3">
          <h6 class="font-weight-bold mb-2">
            <b-icon icon="phone" class="mr-1 text-success"></b-icon>
            Pagamento via M-Pesa
          </h6>
          <p class="small text-muted mb-2">
            Pode pagar via USSD marcando <strong>*150#</strong> e seguindo as instruções,
            ou utilizar o pagamento automático abaixo.
          </p>
          <div class="bg-light rounded p-2 small">
            <div class="d-flex justify-content-between">
              <span class="text-muted">Entidade:</span>
              <strong>171717</strong>
            </div>
            <div class="d-flex justify-content-between">
              <span class="text-muted">Referência:</span>
              <strong class="text-success" style="font-size: 1.1em; letter-spacing: 2px">{{ paymentReference }}</strong>
            </div>
            <div class="d-flex justify-content-between">
              <span class="text-muted">Montante:</span>
              <strong>{{ formatCurrency(selectedTotal) }}</strong>
            </div>
          </div>
        </b-card>

        <!-- Formulário de pagamento directo -->
        <b-card class="border-0 bg-light">
          <h6 class="font-weight-bold mb-3">
            <b-icon icon="lightning" class="mr-1 text-warning"></b-icon>
            Pagamento Instantâneo (Open API)
          </h6>
          <b-form-group label="Número Vodacom M-Pesa (12 dígitos)" label-size="sm" label-class="font-weight-bold">
            <b-form-input
              v-model="mpesaPhone"
              type="number"
              placeholder="258XXXXXXXXX"
              :state="mpesaPhone.length === 12 ? true : (mpesaPhone.length > 0 ? false : null)"
            ></b-form-input>
            <b-form-invalid-feedback>
              O número deve ter exactamente 12 dígitos (ex: 258841234567)
            </b-form-invalid-feedback>
          </b-form-group>

          <b-button
            block
            variant="success"
            class="btn-mbr mt-2"
            :disabled="mpesaPhone.length !== 12 || mpesaProcessing"
            @click="payViaMpesa"
          >
            <b-spinner v-if="mpesaProcessing" small class="mr-1"></b-spinner>
            <b-icon v-else icon="phone" class="mr-1"></b-icon>
            {{ mpesaProcessing ? 'A processar pagamento...' : 'Pagar via M-Pesa' }}
          </b-button>

        </b-card>
      </div>
    </b-modal>

    <!-- ═══════════════ MODAL: FEEDBACK PAGAMENTO M-PESA ═══════════════ -->
    <b-modal
      id="modal-mpesa-feedback"
      centered
      hide-header
      hide-footer
      no-close-on-backdrop
      no-close-on-esc
      size="sm"
      body-class="p-0"
    >
      <div v-if="mpesaResult" class="text-center py-4 px-3">
        <!-- Ícone animado -->
        <div class="mpesa-feedback-icon mb-3">
          <div
            :class="mpesaResult.success ? 'feedback-circle-success' : 'feedback-circle-error'"
            class="feedback-circle mx-auto"
          >
            <b-icon
              :icon="mpesaResult.success ? 'check-lg' : 'x-lg'"
              font-scale="2.5"
              class="text-white"
            ></b-icon>
          </div>
        </div>

        <!-- Mensagem -->
        <h5 class="font-weight-bold mb-2" :class="mpesaResult.success ? 'text-success' : 'text-danger'">
          {{ mpesaResult.success ? 'Pagamento Efectuado!' : 'Pagamento Falhou' }}
        </h5>
        <p class="text-muted mb-2" style="font-size: 0.9rem">
          {{ mpesaResult.message }}
        </p>
        <div v-if="mpesaResult.reference" class="mb-3">
          <small class="text-muted">Referência:</small>
          <div class="font-weight-bold text-primary" style="font-size: 1.1rem; letter-spacing: 1px">
            {{ mpesaResult.reference }}
          </div>
        </div>

        <!-- Barra de progresso para fecho automático -->
        <div class="mt-3">
          <small class="text-muted">A fechar automaticamente...</small>
          <b-progress :value="feedbackCountdown" :max="feedbackCountdownMax" height="4px" class="mt-1"
            :variant="mpesaResult.success ? 'success' : 'danger'"
          ></b-progress>
        </div>
      </div>
    </b-modal>

    <!-- ═══════════════ MODAL: SOLICITAR CRÉDITO ═══════════════ -->
    <b-modal
      id="modal-novo-credito"
      title="Solicitar Novo Crédito"
      centered
      header-bg-variant="success"
      header-text-variant="white"
    >
      <b-form>
        <b-form-group label="Quanto precisa?" label-class="font-weight-bold">
          <b-input-group prepend="MZN">
            <b-form-input
              v-model="newLoanForm.amount"
              type="number"
              placeholder="Ex: 5000.00"
            ></b-form-input>
          </b-input-group>
        </b-form-group>
        <b-form-group label="Número de Prestações" label-class="font-weight-bold">
          <b-form-select
            v-model="newLoanForm.installments"
            :options="installmentOptions"
          ></b-form-select>
        </b-form-group>
        <b-form-group label="Finalidade do Crédito" label-class="font-weight-bold">
          <b-form-input
            v-model="newLoanForm.purpose"
            placeholder="Ex: Capital de giro, Agricultura, Comércio..."
          ></b-form-input>
        </b-form-group>
      </b-form>
      <template #modal-footer="{ cancel }">
        <b-button variant="light" @click="cancel()">Cancelar</b-button>
        <b-button
          variant="success"
          class="btn-mbr"
          @click="submitLoanRequest"
          :disabled="!newLoanForm.amount || !newLoanForm.installments"
        >
          <b-icon icon="send" class="mr-1"></b-icon>
          Enviar Proposta
        </b-button>
      </template>
    </b-modal>

    <!-- ═══════════════ MODAL: ALTERAR SENHA ═══════════════ -->
    <b-modal
      id="modal-change-password"
      title="Alterar Senha"
      centered
      hide-footer
      size="md"
      header-bg-variant="success"
      header-text-variant="white"
      @hidden="resetPasswordForm"
    >
      <b-form @submit.prevent="submitChangePassword">
        <b-form-group label="Senha Actual" label-class="font-weight-bold">
          <b-input-group>
            <b-form-input
              v-model="passwordForm.currentPassword"
              :type="showCurrentPassword ? 'text' : 'password'"
              placeholder="Introduza a sua senha actual"
              required
            ></b-form-input>
            <b-input-group-append>
              <b-button variant="outline-secondary" @click="showCurrentPassword = !showCurrentPassword">
                <b-icon :icon="showCurrentPassword ? 'eye-slash' : 'eye'"></b-icon>
              </b-button>
            </b-input-group-append>
          </b-input-group>
        </b-form-group>

        <b-form-group label="Nova Senha" label-class="font-weight-bold">
          <b-input-group>
            <b-form-input
              v-model="passwordForm.newPassword"
              :type="showNewPassword ? 'text' : 'password'"
              placeholder="Introduza a nova senha (mín. 6 caracteres)"
              required
              :state="passwordForm.newPassword.length > 0 ? passwordForm.newPassword.length >= 6 : null"
            ></b-form-input>
            <b-input-group-append>
              <b-button variant="outline-secondary" @click="showNewPassword = !showNewPassword">
                <b-icon :icon="showNewPassword ? 'eye-slash' : 'eye'"></b-icon>
              </b-button>
            </b-input-group-append>
          </b-input-group>
          <b-form-invalid-feedback :state="passwordForm.newPassword.length >= 6">
            A senha deve ter pelo menos 6 caracteres.
          </b-form-invalid-feedback>
        </b-form-group>

        <b-form-group label="Confirmar Nova Senha" label-class="font-weight-bold">
          <b-input-group>
            <b-form-input
              v-model="passwordForm.confirmPassword"
              :type="showConfirmPassword ? 'text' : 'password'"
              placeholder="Repita a nova senha"
              required
              :state="passwordForm.confirmPassword.length > 0 ? passwordsMatch : null"
            ></b-form-input>
            <b-input-group-append>
              <b-button variant="outline-secondary" @click="showConfirmPassword = !showConfirmPassword">
                <b-icon :icon="showConfirmPassword ? 'eye-slash' : 'eye'"></b-icon>
              </b-button>
            </b-input-group-append>
          </b-input-group>
          <b-form-invalid-feedback :state="passwordsMatch">
            As senhas não coincidem.
          </b-form-invalid-feedback>
        </b-form-group>

        <b-alert v-if="passwordChangeError" variant="danger" show class="mt-2 mb-3">
          <b-icon icon="exclamation-triangle" class="mr-1"></b-icon>
          {{ passwordChangeError }}
        </b-alert>

        <b-alert v-if="passwordChangeSuccess" variant="success" show class="mt-2 mb-3">
          <b-icon icon="check-circle" class="mr-1"></b-icon>
          {{ passwordChangeSuccess }}
        </b-alert>

        <div class="d-flex justify-content-end mt-3">
          <b-button
            variant="light"
            class="mr-2"
            @click="$bvModal.hide('modal-change-password')"
          >
            Cancelar
          </b-button>
          <b-button
            variant="success"
            type="submit"
            :disabled="!canSubmitPasswordChange || passwordChanging"
          >
            <b-spinner v-if="passwordChanging" small class="mr-1"></b-spinner>
            <b-icon v-else icon="check-lg" class="mr-1"></b-icon>
            {{ passwordChanging ? 'A processar...' : 'Alterar Senha' }}
          </b-button>
        </div>
      </b-form>
    </b-modal>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import moment from "moment";

export default {
  name: "CustomerDashboardView",
  data() {
    return {
      activeTab: "dashboard",
      loading: true,
      perPage: 10,
      currentPage: 1,

      // Pagamento M-Pesa
      selectedInstallment: null,
      mpesaPhone: "",
      mpesaProcessing: false,
      mpesaResult: null,
      feedbackCountdown: 0,
      feedbackCountdownMax: 100,
      feedbackTimer: null,

      // Alterar Senha
      passwordForm: {
        currentPassword: "",
        newPassword: "",
        confirmPassword: "",
      },
      showCurrentPassword: false,
      showNewPassword: false,
      showConfirmPassword: false,
      passwordChanging: false,
      passwordChangeError: "",
      passwordChangeSuccess: "",

      // Solicitar crédito
      newLoanForm: {
        amount: "",
        installments: null,
        purpose: "",
      },
      installmentOptions: Array.from({ length: 18 }, (_, i) => ({
        value: i + 1,
        text: `${i + 1} mês(es)`,
      })),

      // Campos da tabela de amortização
      amortizationFields: [
        { key: "installmentOrder", label: "#", class: "text-center" },
        { key: "dueDate", label: "Vencimento" },
        { key: "installment", label: "Prestação", class: "text-right" },
        { key: "forfeit", label: "Juros de Mora", class: "text-right" },
        { key: "totalDue", label: "Total a Pagar", class: "text-right" },
        { key: "status", label: "Estado", class: "text-center" },
        { key: "actions", label: "Acções", class: "text-center" },
      ],

      // Campos do histórico de pagamentos
      transactionFields: [
        { key: "paymentDate", label: "Data", sortable: true },
        { key: "amount", label: "Montante", class: "text-right" },
        { key: "latePaymentInterest", label: "Juros de Mora", class: "text-right" },
        { key: "paymentMethod", label: "Método" },
        { key: "tranzactionReference", label: "Referência" },
        { key: "description", label: "Descrição" },
      ],

      // Campos das prestações vencidas
      overdueFields: [
        { key: "installmentOrder", label: "#" },
        { key: "dueDate", label: "Vencimento" },
        { key: "installment", label: "Valor", class: "text-right" },
        { key: "lateDays", label: "Atraso", class: "text-center" },
        { key: "actions", label: "Acções", class: "text-right" },
      ],

      // Dados da empresa (para cálculos de juros de mora)
      companyData: {},
    };
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "customerPanelData",
      "customerPanelLoans",
      "customerPanelTransactions",
      "customerPanelAmortizations",
      "accounts",
      "token",
    ]),

    firstName() {
      const name = this.customerPanelData.customerName || "";
      return name.split(" ")[0];
    },

    customerInitials() {
      const name = this.customerPanelData.customerName || "";
      const parts = name.split(" ").filter((p) => p.length > 0);
      if (parts.length >= 2) {
        return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
      }
      return parts.length ? parts[0][0].toUpperCase() : "?";
    },

    passwordsMatch() {
      return (
        this.passwordForm.newPassword === this.passwordForm.confirmPassword
      );
    },

    canSubmitPasswordChange() {
      return (
        this.passwordForm.currentPassword.length > 0 &&
        this.passwordForm.newPassword.length >= 6 &&
        this.passwordsMatch
      );
    },

    activeLoans() {
      return this.customerPanelLoans.filter(
        (l) => Number(l.status) === 1 || Number(l.status) === 2
      );
    },

    totalDebt() {
      let total = 0;
      for (const loan of this.activeLoans) {
        const amortizations = this.customerPanelAmortizations[loan.id] || [];
        for (const a of amortizations) {
          const st = Number(a.status);
          if (st === 0 || st === -1) {
            // Soma o valor da prestação
            const installmentAmount = parseFloat(a.installment) || 0;
            total += installmentAmount;
            // Soma juros de mora (calculados no frontend)
            total += this.computeForfeit(a);
          }
        }
      }
      return total;
    },

    totalPaid() {
      return this.customerPanelTransactions.reduce(
        (sum, t) => sum + (parseFloat(t.amount) || 0),
        0
      );
    },

    nextInstallment() {
      let next = null;
      for (const loan of this.activeLoans) {
        const amortizations = this.customerPanelAmortizations[loan.id] || [];
        for (const a of amortizations) {
          if (Number(a.status) === 0) {
            if (!next || moment(a.dueDate).isBefore(moment(next.dueDate))) {
              next = a;
            }
          }
        }
      }
      return next;
    },

    overdueInstallments() {
      const overdue = [];
      for (const loan of this.activeLoans) {
        const amortizations = this.customerPanelAmortizations[loan.id] || [];
        for (const a of amortizations) {
          const st = Number(a.status);
          if ((st === 0 || st === -1) && moment().isAfter(moment(a.dueDate), "day")) {
            const diffDays = moment().diff(moment(a.dueDate), "days");
            overdue.push({ ...a, _lateDays: diffDays });
          }
        }
      }
      return overdue.sort((a, b) => a._lateDays - b._lateDays);
    },

    selectedLateDays() {
      if (!this.selectedInstallment) return 0;
      const diff = moment().diff(moment(this.selectedInstallment.dueDate), "days");
      return diff > 0 ? diff : 0;
    },

    selectedForfeit() {
      if (!this.selectedInstallment) return 0;
      return this.computeForfeit(this.selectedInstallment);
    },

    selectedTotal() {
      if (!this.selectedInstallment) return 0;
      return Math.round((this.selectedInstallment.installment + this.selectedForfeit) * 100) / 100;
    },

    // Referência numérica de 6 dígitos: primeiros 3 = conta do cliente, últimos 3 = ID da prestação
    paymentReference() {
      if (!this.selectedInstallment || !this.customerPanelData.accountNumber) return "------";
      const acct = String(this.customerPanelData.accountNumber);
      const prefix = acct.slice(-3).padStart(3, "0");
      const suffix = String(this.selectedInstallment.id % 1000).padStart(3, "0");
      return prefix + suffix;
    },

    // ID de transacção único para a API M-Pesa (evita duplicação)
    mpesaTransactionId() {
      if (!this.selectedInstallment) return "";
      const ref = this.paymentReference;
      const ts = Date.now().toString(36).slice(-4).toUpperCase();
      return `T${ref}${ts}`;
    },
  },

  beforeDestroy() {
    if (this.feedbackTimer) {
      clearInterval(this.feedbackTimer);
    }
  },

  async created() {
    // Restaurar token no header axios
    if (this.token) {
      axios.defaults.headers.common["Authorization"] = `Bearer ${this.token}`;
    }

    // Carregar dados do cliente
    if (this.customerPanelData && this.customerPanelData.accountNumber) {
      await this.loadAllData();
    } else {
      // Tentar restaurar do localStorage
      const saved = localStorage.getItem("customer");
      if (saved) {
        const customer = JSON.parse(saved);
        this.$store.commit("SET_CUSTOMER_PANEL", customer);
        await this.loadAllData();
      }
    }
  },

  methods: {
    async loadAllData() {
      this.loading = true;
      try {
        const accountNumber = this.customerPanelData.accountNumber;

        // Carregar empréstimos e transacções em paralelo
        await Promise.all([
          this.$store.dispatch("getCustomerPanelLoans", accountNumber),
          this.$store.dispatch("getCustomerPanelTransactions", accountNumber),
        ]);

        // Obter companyId do customerPanelData ou do primeiro empréstimo (fallback)
        let companyId = this.customerPanelData.companyId;
        if (!companyId && this.customerPanelLoans.length > 0) {
          companyId = this.customerPanelLoans[0].companyId;
        }

        // Carregar dados da empresa e canais de pagamento em paralelo
        if (companyId) {
          await Promise.all([
            this.loadCompanyData(companyId),
            this.$store.dispatch("getAllAccounts", companyId).catch((err) => {
              console.error("Erro ao carregar canais de pagamento via Vuex:", err);
            }),
          ]);

          // Fallback: se o Vuex não carregou os accounts, tentar directamente
          if (!this.accounts || this.accounts.length === 0) {
            try {
              const accRes = await axios.get(`/api/accounts/${companyId}`);
              if (accRes.data && accRes.data.success && Array.isArray(accRes.data.result)) {
                this.$store.commit("SET_ACCOUNT", accRes.data.result);
              }
            } catch (accErr) {
              console.error("Fallback de accounts também falhou:", accErr);
            }
          }
        }

        // Carregar amortizações de todos os empréstimos activos (e dos demais para progresso)
        if (this.customerPanelLoans.length > 0) {
          const loanPromises = this.customerPanelLoans.map((loan) =>
            this.$store
              .dispatch("getCustomerPanelAmortizations", loan.id)
              .catch((err) => {
                console.error(`Erro ao carregar amortizações do empréstimo ${loan.id}:`, err);
              })
          );
          await Promise.all(loanPromises);
        }
      } catch (err) {
        console.error("Erro ao carregar dados:", err);
      } finally {
        this.loading = false;
      }
    },

    async loadCompanyData(companyId) {
      try {
        if (companyId) {
          const res = await axios.get(`/api/company/${companyId}`);
          if (res.data && res.data.success) {
            this.companyData = res.data.result;
          }
        }
      } catch (err) {
        console.error("Erro ao carregar dados da empresa:", err);
      }
    },

    async loadAmortizations(loanId) {
      if (
        !this.customerPanelAmortizations[loanId] ||
        this.customerPanelAmortizations[loanId].length === 0
      ) {
        await this.$store.dispatch("getCustomerPanelAmortizations", loanId);
      }
    },

    loanAmortizations(loanId) {
      return this.customerPanelAmortizations[loanId] || [];
    },

    // ── Cálculos ──

    computeForfeit(amortization) {
      if (!amortization || Number(amortization.status) === 1) return 0;
      const diffDays = moment().diff(moment(amortization.dueDate), "days");
      if (diffDays <= 0) return 0;
      // Converte a percentagem para taxa decimal: ex: 2 → 0.02
      const dailyRate = (parseFloat(this.companyData.forfeit) || 0) / 100;
      return Math.round((parseFloat(amortization.installment) || 0) * dailyRate * diffDays * 100) / 100;
    },

    getLoanProgress(loan) {
      const amortizations = this.customerPanelAmortizations[loan.id] || [];
      if (amortizations.length === 0) return 0;
      const paid = amortizations.filter((a) => Number(a.status) === 1).length;
      return Math.round((paid / amortizations.length) * 100);
    },

    getLoanProgressText(loan) {
      const amortizations = this.customerPanelAmortizations[loan.id] || [];
      if (amortizations.length === 0) return "0/0";
      const paid = amortizations.filter((a) => Number(a.status) === 1).length;
      return `${paid}/${amortizations.length} prestações pagas`;
    },

    // ── Status labels ──

    getLoanStatusVariant(status) {
      const map = { 0: "warning", 1: "success", 2: "info", 3: "secondary", "-1": "danger" };
      return map[status] || "secondary";
    },

    getLoanStatusLabel(status) {
      const map = {
        0: "Submetido",
        1: "Activo",
        2: "Em curso",
        3: "Concluído",
        "-1": "Rejeitado",
      };
      return map[status] || "Desconhecido";
    },

    getInstallmentStatusVariant(item) {
      const st = Number(item.status);
      if (st === 1) return "success";
      if (st === -1) return "warning";
      const isOverdue = moment().isAfter(moment(item.dueDate), "day");
      return isOverdue ? "danger" : "primary";
    },

    getInstallmentStatusLabel(item) {
      const st = Number(item.status);
      if (st === 1) return "Paga";
      if (st === -1) return "Parcial";
      const isOverdue = moment().isAfter(moment(item.dueDate), "day");
      return isOverdue ? "Vencida" : "Pendente";
    },

    getPaymentMethodLabel(method) {
      const methods = {
        1: "Caixa",
        2: "Depósito",
        3: "Transferência",
        4: "POS",
        5: "Cheque",
        6: "M-Pesa USSD",
        7: "M-Pesa API",
        8: "E-Mola",
      };
      return methods[method] || "Outro";
    },

    getPaymentMethodVariant(method) {
      if (method === 6 || method === 7) return "danger";
      if (method === 8) return "warning";
      return "secondary";
    },

    // ── Formatação ──

    formatCurrency(value) {
      const num = parseFloat(value) || 0;
      return new Intl.NumberFormat("pt-MZ", {
        style: "currency",
        currency: "MZN",
        minimumFractionDigits: 2,
      }).format(num);
    },

    formatDate(date) {
      if (!date) return "--";
      return moment(date).format("DD/MM/YYYY");
    },

    formatOrder(value) {
      // Remove a palavra "prestação" se existir nos dados antigos (ex: "1ª prestação" → "1ª")
      if (!value) return "";
      return String(value).replace(/\s*prestação/i, "");
    },

    // ── Pagamento M-Pesa ──

    openPaymentModal(installment) {
      this.selectedInstallment = installment;
      this.mpesaPhone = this.customerPanelData.customerPhone
        ? this.customerPanelData.customerPhone.replace(/\D/g, "")
        : "";
      this.mpesaProcessing = false;
      this.mpesaResult = null;
      this.$bvModal.show("modal-pagamento-mpesa");
    },

    async payViaMpesa() {
      if (this.mpesaPhone.length !== 12) {
        this.showMpesaFeedback({
          success: false,
          message: "O número Vodacom deve ter exactamente 12 dígitos.",
        });
        return;
      }

      this.mpesaProcessing = true;
      this.mpesaResult = null;

      try {
        const res = await axios.put("/api/mpesa/receive", {
          from: this.mpesaPhone,
          transaction: this.mpesaTransactionId,
          amount: this.selectedTotal,
          reference: this.paymentReference,
        });

        const data = res.data;
        if (data.success) {
          const response = data.result;
          if (
            response.output_ResponseCode === "INS-0" ||
            response.output_ResponseCode === "INS-0 "
          ) {
            // Registar transacção
            await this.addMpesaTransaction(response);

            // Fechar modal de pagamento e mostrar feedback de sucesso
            this.$bvModal.hide("modal-pagamento-mpesa");
            this.showMpesaFeedback({
              success: true,
              message: "O pagamento foi efectuado com sucesso!",
              reference: response.output_TransactionID || this.paymentReference,
            });

            // Recarregar dados
            this.loadAllData();
          } else {
            this.$bvModal.hide("modal-pagamento-mpesa");
            this.showMpesaFeedback({
              success: false,
              message: `Erro M-Pesa: ${response.output_ResponseDesc || "Tente novamente."}`,
            });
          }
        } else {
          this.$bvModal.hide("modal-pagamento-mpesa");
          this.showMpesaFeedback({
            success: false,
            message: "Erro ao processar pagamento. Tente novamente ou use o USSD *150#.",
          });
        }
      } catch (err) {
        console.error("Erro M-Pesa:", err);
        this.$bvModal.hide("modal-pagamento-mpesa");
        this.showMpesaFeedback({
          success: false,
          message: "Erro de comunicação. Verifique a sua ligação e tente novamente.",
        });
      } finally {
        this.mpesaProcessing = false;
      }
    },

    showMpesaFeedback(result) {
      // Limpar timer anterior se existir
      if (this.feedbackTimer) {
        clearInterval(this.feedbackTimer);
        this.feedbackTimer = null;
      }

      this.mpesaResult = result;
      this.feedbackCountdown = 0;
      this.$bvModal.show("modal-mpesa-feedback");

      // Fecho automático com barra de progresso (4 segundos)
      const totalMs = 4000;
      const intervalMs = 50;
      const step = (intervalMs / totalMs) * 100;

      this.feedbackTimer = setInterval(() => {
        this.feedbackCountdown += step;
        if (this.feedbackCountdown >= 100) {
          clearInterval(this.feedbackTimer);
          this.feedbackTimer = null;
          this.$bvModal.hide("modal-mpesa-feedback");
        }
      }, intervalMs);
    },

    async addMpesaTransaction(mpesaResponse) {
      const mpesaTxId = mpesaResponse.output_TransactionID
        ? mpesaResponse.output_TransactionID.toUpperCase()
        : "";

      const transactionData = {
        tranzactionReference: mpesaTxId || this.paymentReference,
        accountNumber: this.customerPanelData.accountNumber,
        phoneNumber: this.mpesaPhone,
        staffName: "Portal do Mutuário",
        companyId: this.customerPanelData.companyId || 1,
        amount: this.selectedInstallment.installment,
        latePaymentInterest: this.selectedForfeit,
        interestRateAmount: this.selectedInstallment.rateAmount || 0,
        amortizationLoanId: this.selectedInstallment.id,
        loanId: this.selectedInstallment.loanId,
        paymentDate: moment().format("YYYY-MM-DD"),
        paymentMethod: 7,
        receiptUrl: "",
        description: `Pagamento da prestação ${this.selectedInstallment.installmentOrder} via M-Pesa. Ref: ${this.paymentReference}. TX: ${mpesaTxId}`,
      };

      try {
        await axios.post("/api/tranzaction", transactionData);
      } catch (err) {
        console.error("Erro ao registar transacção:", err);
      }
    },

    // ── Solicitar crédito ──

    submitLoanRequest() {
      this.$bvToast.toast(
        `Proposta de crédito de ${this.formatCurrency(this.newLoanForm.amount)} em ${this.newLoanForm.installments} prestações enviada. Aguarde contacto do gestor.`,
        {
          title: "Proposta Enviada",
          variant: "success",
          solid: true,
          toaster: "b-toaster-top-center",
          autoHideDelay: 5000,
        }
      );
      this.newLoanForm = { amount: "", installments: null, purpose: "" };
      this.$bvModal.hide("modal-novo-credito");
    },

    // ── Logout ──

    // ── Alterar Senha ──

    resetPasswordForm() {
      this.passwordForm = {
        currentPassword: "",
        newPassword: "",
        confirmPassword: "",
      };
      this.showCurrentPassword = false;
      this.showNewPassword = false;
      this.showConfirmPassword = false;
      this.passwordChanging = false;
      this.passwordChangeError = "";
      this.passwordChangeSuccess = "";
    },

    async submitChangePassword() {
      if (!this.canSubmitPasswordChange) return;

      this.passwordChanging = true;
      this.passwordChangeError = "";
      this.passwordChangeSuccess = "";

      try {
        const res = await axios.post("/api/customer/changePassword", {
          customerId: this.customerPanelData.id,
          currentPassword: this.passwordForm.currentPassword,
          newPassword: this.passwordForm.newPassword,
        });

        if (res.data && res.data.success) {
          this.passwordChangeSuccess = res.data.message || "Senha alterada com sucesso!";
          this.showToast("Sucesso", "success", "Senha alterada com sucesso!");
          // Limpar formulário após 2 segundos e fechar modal
          setTimeout(() => {
            this.$bvModal.hide("modal-change-password");
          }, 2000);
        } else {
          this.passwordChangeError = res.data.message || "Erro ao alterar a senha.";
        }
      } catch (err) {
        console.error("Erro ao alterar senha:", err);
        this.passwordChangeError =
          (err.response && err.response.data && err.response.data.message) ||
          "Erro de comunicação com o servidor.";
      } finally {
        this.passwordChanging = false;
      }
    },

    async doLogout() {
      await this.$store.dispatch("customerDoLogout");
      this.$router.replace("/");
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(msg, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 3000,
      });
    },

    // ── Recibo de Pagamento ──

    findTransactionForInstallment(installment) {
      // 1. Busca exacta por amortizationLoanId (chave primária da prestação)
      const exact = this.customerPanelTransactions.find(
        (t) => Number(t.amortizationLoanId) === Number(installment.id)
      );
      if (exact) return exact;

      // 2. Fallback: busca por loanId + montante compatível (para dados antigos sem amortizationLoanId)
      const byLoan = this.customerPanelTransactions.filter(
        (t) => Number(t.loanId) === Number(installment.loanId)
      );
      if (byLoan.length === 1) return byLoan[0];

      // 3. Último fallback: correspondência por montante mais próximo
      const installmentAmount = parseFloat(installment.installment) || 0;
      return byLoan.find(
        (t) => Math.abs((parseFloat(t.amount) || 0) - installmentAmount) < 1
      ) || null;
    },

    printReceipt(installment) {
      const customer = this.customerPanelData;
      const transaction = this.findTransactionForInstallment(installment);
      const company = this.companyData || {};
      const companyName = company.companyName || company.smsSender || "Microcrédito";

