      const hasTransaction = !!transaction;
      const paymentDate = hasTransaction ? this.formatDate(transaction.paymentDate) : "--";
      const paymentMethod = hasTransaction ? this.getPaymentMethodLabel(transaction.paymentMethod) : "--";
      const reference = hasTransaction ? (transaction.tranzactionReference || "--") : "--";
      const staffName = hasTransaction ? (transaction.staffName || "--") : "--";
      const amountPaid = hasTransaction ? (parseFloat(transaction.amount) || 0) : 0;
      const lateInterest = hasTransaction ? (parseFloat(transaction.latePaymentInterest) || 0) : 0;
      const totalPaid = amountPaid + lateInterest;
      const installmentAmount = parseFloat(installment.installment) || 0;

      // Número do recibo: ID da transacção (ou referência gerada)
      const receiptNumber = hasTransaction
        ? String(transaction.id).padStart(6, "0")
        : "--";

      const html = `
