              <div class="section-title">Dados do Mutuário</div>
              <div class="receipt-row"><span class="label">Nome</span><span class="value">${customer.customerName || "--"}</span></div>
              <div class="receipt-row"><span class="label">Nº da Conta</span><span class="value">${customer.accountNumber || "--"}</span></div>
