    // ── Extrato de Prestações ──

    async downloadStatement(loan) {
      // Garantir que as amortizações estejam carregadas
      if (
        !this.customerPanelAmortizations[loan.id] ||
        this.customerPanelAmortizations[loan.id].length === 0
      ) {
        await this.$store.dispatch("getCustomerPanelAmortizations", loan.id);
      }

      const customer = this.customerPanelData;
      const company = this.companyData || {};
      const companyName = company.companyName || company.smsSender || "Microcrédito";
      const amortizations = this.customerPanelAmortizations[loan.id] || [];
      const transactions = this.customerPanelTransactions || [];

      // Mapear transacções por amortizationLoanId
      const txMap = {};
      transactions.forEach((t) => {
        if (t.amortizationLoanId) {
          if (!txMap[t.amortizationLoanId]) txMap[t.amortizationLoanId] = [];
          txMap[t.amortizationLoanId].push(t);
        }
      });

      // Construir linhas da tabela
      let tableRows = "";
      let totalInstallments = 0;
      let totalForfeit = 0;
      let totalPayments = 0;

      amortizations.forEach((a) => {
        const st = Number(a.status);
        const installmentVal = parseFloat(a.installment) || 0;
        const statusLabel = this.getInstallmentStatusLabel(a);
        const statusColor =
          st === 1 ? "#28a745" : st === -1 ? "#ffc107" : moment().isAfter(moment(a.dueDate), "day") ? "#dc3545" : "#007bff";

        totalInstallments += installmentVal;

        // Encontrar pagamentos desta prestação
        const relatedTx = txMap[a.id] || [];
        const txAmount = relatedTx.reduce((s, t) => s + (parseFloat(t.amount) || 0), 0);
        totalPayments += txAmount;

        // Juros de mora: para prestações pagas, usar valor REAL da transacção; caso contrário, calcular
        let forfeitVal = 0;
        if (st === 1 && relatedTx.length > 0) {
          // Prestação paga: usar latePaymentInterest registado na transacção
          forfeitVal = relatedTx.reduce((s, t) => s + (parseFloat(t.latePaymentInterest) || 0), 0);
        } else if (st === 0 || st === -1) {
          // Prestação pendente/em atraso: calcular com data actual
          forfeitVal = this.computeForfeit(a);
        }
        totalForfeit += forfeitVal;

        const txInfo = relatedTx.length > 0
          ? relatedTx.map((t) => `${this.formatDate(t.paymentDate)} - ${this.formatCurrency(t.amount)} (${this.getPaymentMethodLabel(t.paymentMethod)})`).join("<br>")
          : '<span style="color:#999">--</span>';

        tableRows += `
          <tr>
            <td style="text-align:center;font-weight:600">${a.installmentOrder}</td>
            <td>${this.formatDate(a.dueDate)}</td>
            <td style="text-align:right">${this.formatCurrency(installmentVal)}</td>
            <td style="text-align:right;color:${forfeitVal > 0 ? '#dc3545' : '#999'}">${forfeitVal > 0 ? this.formatCurrency(forfeitVal) : "--"}</td>
            <td style="text-align:right;font-weight:600">${this.formatCurrency(installmentVal + forfeitVal)}</td>
            <td style="text-align:center"><span style="background:${statusColor};color:#fff;padding:2px 10px;border-radius:10px;font-size:11px">${statusLabel}</span></td>
            <td style="font-size:12px">${txInfo}</td>
          </tr>
        `;
      });

      const saldoDevedor = totalInstallments + totalForfeit - totalPayments;

      const html = `
        <!DOCTYPE html>
        <html lang="pt">
        <head>
          <meta charset="UTF-8">
          <title>Extrato - Contrato #${loan.accountNumber}-${loan.id}</title>
          <style>
            * { margin: 0; padding: 0; box-sizing: border-box; }
