            .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #009640; padding-bottom: 16px; margin-bottom: 20px; }
            .header h1 { font-size: 20px; color: #009640; }
            .header .subtitle { font-size: 12px; color: #666; }
            .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 20px; }
            .info-box { background: #f8f9fa; padding: 12px; border-radius: 6px; border-left: 3px solid #009640; }
            .info-box .label { font-size: 11px; color: #999; text-transform: uppercase; letter-spacing: 0.5px; }
            .info-box .value { font-weight: 700; font-size: 14px; margin-top: 2px; }
            table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
            th { background: #009640; color: #fff; padding: 8px 10px; text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.3px; }
            td { padding: 8px 10px; border-bottom: 1px solid #eee; vertical-align: top; }
            tr:hover { background: #f9f9f9; }
            .summary { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 20px; }
            .summary-box { text-align: center; padding: 14px; border-radius: 8px; }
            .summary-box .num { font-size: 18px; font-weight: 700; }
            .summary-box .lbl { font-size: 11px; color: #666; margin-top: 2px; }
            .bg-green { background: rgba(0,150,64,0.1); }
            .bg-red { background: rgba(220,53,69,0.1); }
            .bg-blue { background: rgba(0,123,255,0.1); }
            .bg-orange { background: rgba(255,193,7,0.15); }
            .text-green { color: #009640; }
            .text-red { color: #dc3545; }
            .text-blue { color: #007bff; }
            .text-orange { color: #e67e00; }
            .footer { text-align: center; font-size: 11px; color: #999; border-top: 1px dashed #ddd; padding-top: 14px; margin-top: 10px; }
            @media print { body { padding: 10px; font-size: 11px; } .no-print { display: none !important; } th { -webkit-print-color-adjust: exact; print-color-adjust: exact; } .summary-box { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
          </style>
        </head>
        <body>
          <div class="header">
            <div>
              <h1>EXTRATO DE PRESTAÇÕES</h1>
              <div class="subtitle">Contrato #${loan.accountNumber}-${loan.id} | ${companyName}</div>
            </div>
            <div style="text-align:right">
              <div style="font-size:12px;color:#666">Data de emissão</div>
              <div style="font-weight:700">${moment().format("DD/MM/YYYY HH:mm")}</div>
            </div>
          </div>

          <div class="info-grid">
            <div class="info-box">
              <div class="label">Mutuário</div>
              <div class="value">${customer.customerName || "--"}</div>
            </div>
            <div class="info-box">
              <div class="label">Nº da Conta</div>
              <div class="value">${customer.accountNumber || "--"}</div>
            </div>
            <div class="info-box">
              <div class="label">Montante Financiado</div>
              <div class="value text-green">${this.formatCurrency(loan.amount)}</div>
            </div>
            <div class="info-box">
              <div class="label">Taxa de Juro</div>
              <div class="value">${(loan.interestRate * 100).toFixed(1)}% | ${loan.numberOfInstallments} prestações</div>
            </div>
          </div>

          <div class="summary">
            <div class="summary-box bg-green">
              <div class="num text-green">${this.formatCurrency(totalPayments)}</div>
              <div class="lbl">Total Pago</div>
            </div>
            <div class="summary-box bg-blue">
              <div class="num text-blue">${this.formatCurrency(totalInstallments)}</div>
              <div class="lbl">Total Prestações</div>
            </div>
            <div class="summary-box bg-orange">
              <div class="num text-orange">${this.formatCurrency(totalForfeit)}</div>
              <div class="lbl">Juros de Mora</div>
            </div>
            <div class="summary-box bg-red">
              <div class="num text-red">${this.formatCurrency(Math.max(0, saldoDevedor))}</div>
              <div class="lbl">Saldo em Dívida</div>
            </div>
          </div>

          <table>
            <thead>
              <tr>
                <th style="text-align:center">Nº</th>
                <th>Vencimento</th>
                <th style="text-align:right">Prestação</th>
                <th style="text-align:right">Mora</th>
